<?php declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('gifts.manage');if(is_post()){verify_csrf();$action=(string)input('action');try{$pdo=db();$pdo->beginTransaction();if($action==='gift'){$qty=(int)input('total_quantity');if($qty<1)throw new InvalidArgumentException('Quantity must be positive.');$pdo->prepare('INSERT INTO gifts(name,description,image_path,campaign,total_quantity,valid_from,valid_until,status,created_by) VALUES(?,?,?,?,?,?,?, ?,?)')->execute([trim((string)input('name')),trim((string)input('description')),trim((string)input('image_path'))?:null,trim((string)input('campaign'))?:null,$qty,trim((string)input('valid_from'))?str_replace('T',' ',(string)input('valid_from')):null,trim((string)input('valid_until'))?str_replace('T',' ',(string)input('valid_until')):null,strtoupper((string)input('status')),admin()['id']]);$record=(string)$pdo->lastInsertId();}elseif($action==='code'){$plain=strtoupper(bin2hex(random_bytes(8)));$reference=transaction_code('GFT');$days=setting_int('reward_code_valid_days',30);$pdo->prepare('INSERT INTO reward_codes(code_reference,code_hash,user_id,gift_id,status,expires_at,created_by) VALUES(?,?,?, ?,"ACTIVE",DATE_ADD(NOW(),INTERVAL '.$days.' DAY),?)')->execute([$reference,hash('sha256',$plain),(int)input('user_id'),(int)input('gift_id'),admin()['id']]);$record=(string)$pdo->lastInsertId();$_SESSION['_gift_code_once']=$plain;}else throw new InvalidArgumentException('Invalid action.');audit_log((int)admin()['id'],'GIFT_'.strtoupper($action),'gifts',$record??null);$pdo->commit();flash('success',$action==='code'?'Code generated. Copy it now; only a hash is stored.':'Gift created.');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();flash('error',$e->getMessage());}redirect('/admin/gifts/index.php');}$gifts=db()->query('SELECT * FROM gifts ORDER BY id DESC')->fetchAll();$codes=db()->query('SELECT rc.*,u.name user_name,g.name gift_name FROM reward_codes rc JOIN users u ON u.id=rc.user_id JOIN gifts g ON g.id=rc.gift_id ORDER BY rc.id DESC LIMIT 200')->fetchAll();$once=$_SESSION['_gift_code_once']??null;unset($_SESSION['_gift_code_once']);$pageTitle='Gifts & reward codes';$pageSubtitle='Single-use, expirable codes are stored only as SHA-256 hashes';require APP_ROOT.'/includes/header.php';?>
<?php if($once):?><section class="panel one-time"><h2>One-time redemption code</h2><input readonly value="<?=e($once)?>"></section><?php endif?><div class="grid detail-grid"><section class="panel"><h2>Create gift</h2><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="action" value="gift"><input name="name" placeholder="Gift name" required><textarea name="description" placeholder="Description"></textarea><input name="campaign" placeholder="Campaign"><input name="image_path" placeholder="Image URL/path"><input type="number" name="total_quantity" min="1" placeholder="Quantity" required><input type="datetime-local" name="valid_from"><input type="datetime-local" name="valid_until"><select name="status"><option>DRAFT</option><option>ACTIVE</option><option>INACTIVE</option></select><button class="btn">Create gift</button></form></section><section class="panel"><h2>Issue code</h2><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="action" value="code"><input type="number" min="1" name="user_id" placeholder="User ID" required><select name="gift_id" required><?php foreach($gifts as $g):?><option value="<?=e($g['id'])?>"><?=e($g['name'])?> (<?=e($g['redeemed_quantity'])?>/<?=e($g['total_quantity'])?>)</option><?php endforeach?></select><button class="btn">Generate code</button></form></section></div><section class="panel"><h2>Issued codes</h2><div class="table-wrap"><table><thead><tr><th>Reference</th><th>User</th><th>Gift</th><th>Status</th><th>Expires</th><th>Redeemed</th></tr></thead><tbody><?php foreach($codes as $c):?><tr><td><?=e($c['code_reference'])?></td><td><?=e($c['user_name'])?></td><td><?=e($c['gift_name'])?></td><td><span class="badge <?=strtolower(e($c['status']))?>"><?=e($c['status'])?></span></td><td><?=e($c['expires_at']??'Never')?></td><td><?=e($c['redeemed_at']??'—')?></td></tr><?php endforeach?></tbody></table></div></section><?php require APP_ROOT.'/includes/footer.php';
